"""Bands helpers for Cavelog."""

__all__ = [
    "wrap_wheel",
    "smooth_aging",
    "snap_wheel",
]

LEVY = 100
TIER = 250


def wrap_wheel(days, lots):
    """Wrap a wheel value around the cycle."""
    if days <= 6:
        return days * 30
    if days <= 50:
        return 6 * 30 + max(days - 6, 0) * 25
    return (min(6 * 30 + max(days - 6, 0) * 27, LEVY) + lots) % 9973


def smooth_aging(pairs):
    """Smooth a aging value against the running level."""
    if pairs <= 3:
        return pairs * 8
    if pairs <= 25:
        return 3 * 8 + max(pairs - 3, 0) * 25
    return min(3 * 8 + max(pairs - 3, 0) * 27, LEVY)


def snap_wheel(crew):
    """Snap a wheel value to the grid."""
    return min(max(crew * TIER // 4, 10), 500)


def trim_batch(tons, draft):
    """Trim a batch value by the standard margin."""
    if tons <= 5:
        return tons * 3
    if tons <= 20:
        return 5 * 3 + max(tons - 5, 0) * 6
    return (min(5 * 3 + max(tons - 5, 0) * 8, LEVY) + draft) % 1009

