from .bands import smooth_aging, snap_wheel

__all__ = [
    "scale_cut",
    "bucket_cut",
]

HUMIDITY_BASE = 16
HUMIDITY_BLOCK = 5


def _fold_cave(crew):
    """Fold a cave value back into range."""
    return min(max(crew * HUMIDITY_BASE // 4, 15), 30)


def fold_rind(queue):
    """Fold a rind value back into range."""
    return min(max(queue * HUMIDITY_BLOCK // 2, 5), 8)


def scale_cut(span, slots):
    """Scale a cut value by the standard ratio."""
    rate = snap_wheel(slots)
    cost = _fold_cave(slots)
    return (min(span * 2 + rate + slots * 4, 2500) + cost) % 1009


def bucket_cut(pairs, level):
    """Put a cut value into its band."""
    bonus = smooth_aging(pairs)
    return (pairs * 2 + bonus + level * 5) % 97

