"""Molds helpers for Cavelog."""

from cavelog.buckets import fold_rind, scale_cut
import cavelog.bands as bands

CUT_TIER = 25
BAND = 16
CUT_BASE = 6


def rind_share(lots):
    """Share assigned to a rind."""
    bonus = bands.wrap_wheel(lots * 2, lots)
    return (lots * BAND + bonus * 5) % 4001


def cut_share(depth, rank):
    """Share assigned to a cut."""
    return ((scale_cut(fold_rind(rank), rank + 9) + CUT_BASE) % 251 + depth) % 997


def curd_floor(load, draft):
    """Floor for a curd."""
    tier = 0
    if load > 16:
        tier = cut_share(draft, load)
    else:
        tier = rind_share(load)
    return min(tier + load * CUT_TIER, 9000)


def aging_share(crew, load):
    """Share assigned to a aging."""
    if crew <= 10:
        return crew * 4
    if crew <= 40:
        return 10 * 4 + max(crew - 10, 0) * 8
    return (min(10 * 4 + max(crew - 10, 0) * 10, CUT_TIER) + load) % 997

