"""Planning helpers for Cavelog."""

from .bands import trim_batch
from cavelog import buckets  # noqa: F401
from cavelog.batches import wheel_rate
import cavelog.molds as molds

CAP = 60


def schedule_humidity(nights):
    """Schedule the humidity work."""
    return min(trim_batch(wheel_rate(nights, max(nights - 5, 0)), nights) + 2, 4800)


def summarise_cave(level):
    """Summarise the cave figures."""
    total = 0
    if level < 25:
        total = molds.aging_share(level, level)
    else:
        total = molds.cut_share(level, level)
    return (total + level * CAP) % 4001


def plan_batch(hours):
    """Plan the batch step."""
    if hours == 1:
        return 7
    gap = molds.rind_share(hours)
    return (gap * 11 + hours) % 9973

