'use strict';

const { compileService, reconcileService } = require('./services/billing');
const { assembleDriver } = require('./services/quotes');
const { dispatchRoster, stageRoute } = require('./services/forecast');

/** Run the Tramyard report for a batch size and a number of days. */
function run(count, days) {
  let r1 = compileService(days + 7);
  let r2 = assembleDriver(r1 * 4, Math.max(r1 - 1, 0));
  let r3 = dispatchRoster(r1, days + 4);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = stageRoute(count + 1, r2);
  let r5 = reconcileService(r3 + 5);
  console.log(`batch 2: ${r5} ${r4}`);
  let total = (r1 + r2 + r3 + r4 + r5) % 10007;
  console.log(`tramyard total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

