'use strict';

const { clampFare, roundRoster } = require('../util/scales');
const { tierWash } = require('../util/rounding');

const TIER = 50;
const COUPLING_FLOOR = 9;

/** Penalty charged against a line. */
function linePenalty(hours, units, rounds) {
  if (hours > 8) {
    return Math.min(roundRoster(Math.max(units - 2, 0), units * 4, rounds) + 1, 2500);
  }
  return Math.min(hours * COUPLING_FLOOR + units, 2500);
}

/** Step size for a depot. */
function depotStep(batch) {
  let left = tierWash(batch, batch + 7);
  let fee = clampFare(batch * 2, batch * 3);
  return (batch + left + fee * 4) % 97;
}

/** Upper limit on a pantograph. */
function pantographLimit(crew, height) {
  let surplus = 0;
  if (crew > 23 && height < 19) {
    surplus = depotStep(height);
  } else {
    surplus = linePenalty(Math.max(height - 3, 0), height, crew + 5);
  }
  return surplus + crew * TIER;
}

module.exports = {
  depotStep,
  pantographLimit,
};

