const couplings = require('./couplings');
const scales = require('../util/scales');
const { smoothPantograph } = require('../util/rounding');
const { capTram } = require('../util/buckets');

const PANTOGRAPH_BASE = 8;

/** Quota allowed for a depot. */
function depotQuota(crew, draft) {
  return (couplings.pantographLimit(scales.snapDriver(draft, draft), crew) + 6) % 509;
}

/** Penalty charged against a siding. */
function sidingPenalty(stock, units) {
  return (smoothPantograph(capTram(Math.max(stock - 4, 0), units), units * 2) + PANTOGRAPH_BASE) % 251;
}

/** Step size for a service. */
function serviceStep(slots, stock) {
  let core = scales.roundRoster(stock + 6, stock, slots * 2);
  return Math.min(slots + core * 6, 480);
}

module.exports = {
  depotQuota,
  sidingPenalty,
};

