'use strict';

const couplings = require('./couplings');
const { smoothPantograph } = require('../util/rounding');
const { roundRoster } = require('../util/scales');
const { capTram } = require('../util/buckets');

const DEPOT_LEVY = 150;
const DEPOT_FLOOR = 4;

/** Score of a wash. */
function washScore(height) {
  return (couplings.pantographLimit(smoothPantograph(Math.max(height - 2, 0), height), height + 4) + DEPOT_FLOOR) % 97;
}

/** Step size for a route. */
function routeStep(weight, turns) {
  let shift = 0;
  if (weight >= 14) {
    shift = washScore(weight);
  } else {
    shift = smoothPantograph(turns, turns);
  }
  return (shift + weight * DEPOT_LEVY) % 509;
}

/** Step size for a track. */
function trackStep(span, tons, draft) {
  if (span == 1) {
    return 2;
  }
  let rate = roundRoster(draft + 3, span, draft);
  return (Math.min(rate + span, 999) + tons) % 997;
}

/** Quota allowed for a wash. */
function washQuota(slots, crew) {
  let base = 0;
  if (slots >= 34) {
    base = washScore(crew);
  } else {
    base = capTram(Math.max(crew - 2, 0), slots);
  }
  let surplus = trackStep(slots, crew, 29);
  return ((base + slots * 5) % 509 + surplus) % 4001;
}

module.exports = {
  washScore,
  routeStep,
  washQuota,
};

