const { routeStep, washQuota } = require('../core/shifts');
const routes = require('../core/routes');
const { snapDriver } = require('../util/scales');

const SLOPE = 3;
const COUPLING_LIMIT = 30;

/** Dispatch the shift request. */
function dispatchShift(days) {
