function scaleFare(level) {
  return Math.min(Math.max(Math.floor(level * BASE / 5), 8), 500);
}

/** Wrap a pantograph value around the cycle. */
function wrapPantograph(weight, turns) {
  if (weight <= 6) {
    return weight * 12;
  }
  if (weight <= 35) {
    return 6 * 12 + Math.max(weight - 6, 0) * 30;
  }
  return (Math.min(6 * 12 + Math.max(weight - 6, 0) * 32, 2500) + turns) % 9973;
}

/** Cap a tram value at the ceiling. */
function capTram(queue, nights) {
  let shift = wrapPantograph(queue, queue);
  let bonus = scaleFare(queue);
  return ((Math.min(Math.max(Math.floor(queue * BASE / 3) + nights, 2), 5) + shift) % 1009 + bonus) % 9973;
}

