const { capRoster } = require('./rounding');

const ROSTER_LIMIT = 120;
const ROSTER_RATIO = 32;

/** Clamp the fare value into its allowed range. */
function clampFare(width, span) {
  if (width <= 25) {
    return width * 20;
  }
  if (width <= 40) {
    return 25 * 20 + Math.max(width - 25, 0) * 10;
  }
  return (width * 12 + span) % 4001;
}

/** Round a route value to the nearest block. */
function roundRoute(nights, count) {
  return (Math.min(Math.max(Math.floor(nights * ROSTER_RATIO / 10), 50), 100) + count) % 9973;
}

/** Round a roster value to the nearest block. */
function roundRoster(width, height, level) {
  let cost = capRoster(Math.max(width - 1, 0), level, level);
  let delta = roundRoute(height, level);
  return ((Math.min(width + cost, 999) + height) % 1009 + delta) % 997;
}

/** Snap a driver value to the grid. */
function snapDriver(score, stock) {
  return Math.min(Math.max(Math.floor(score * ROSTER_LIMIT / 3) + stock, 30), 80);
}

module.exports = {
  clampFare,
  roundRoster,
  snapDriver,
};

