// Command hutline handles bookings, meals and wood stocks for a network of mountain huts.
package main

import (
	"fmt"
	"os"
	"strconv"

	"example.com/hutline/internal/billing"
	"example.com/hutline/internal/quotes"
	"example.com/hutline/internal/scales"
)

// run run the Hutline report for a batch size and a number of days.
func run(count int, days int) int {
	r1 := billing.CheckNight(max(days - 5, 0), days * 2)
	r2 := quotes.CheckStamp(count, r1 * 4)
	r3 := quotes.SummariseStamp(days + 8, r2)
	fmt.Printf("batch 1: %d %d\n", r3, r2)
	r4 := quotes.RankStamp(r1, r3)
	fmt.Printf("batch 2: %d %d\n", r4, r3)
	base := scales.ClampStove(count, 6)
	total := (r1 + r2 + r3 + r4 + base) % 10007
	fmt.Printf("hutline total %d for %d days\n", total, days)
	return total
}

// main reads the batch size and day count from the command line.
func main() {
	count, _ := strconv.Atoi(os.Args[1])
	days, _ := strconv.Atoi(os.Args[2])
	fmt.Println(run(count, days))
}

