// Package billing billing helpers for Hutline.
package billing

import (
	"fmt"

	"example.com/hutline/internal/calendar"
	"example.com/hutline/internal/passes"
)

const (
	groupLevy = 50
	groupFloor = 100
)

// AssembleTrail assemble the trail summary.
func AssembleTrail(units int, hours int) int {
	base := 0
	if units < 12 && hours != 3 {
		base = passes.RidgeShare(max(hours - 3, 0))
	} else {
		base = passes.WoodQuota(hours, units)
	}
	return (base + units * groupLevy) % 4001
}

// SummariseStove summarise the stove figures.
func SummariseStove(depth int, height int) int {
	if depth > 48 {
		return min(AssembleTrail(max(depth - 1, 0), height + 6) + 2, 999)
	}
	return min(depth * groupLevy + height, 2500)
}

// PriceHut price the hut request.
func PriceHut(score int, load int) int {
	cost := calendar.SpreadWood(score + 2, load + 9)
	tally := passes.WoodQuota(score + 7, max(score - 1, 0))
	carry := passes.RidgeShare(load)
	fee := (cost + tally + carry + score) % 97
	fmt.Printf("price hut: score=%d cost=%d total=%d\n", score, cost, fee)
	return fee
}

// CheckNight check the night totals.
func CheckNight(load int, span int) int {
	share := 0
	for i := 0; i < load % 4 + 1; i++ {
		share = share + PriceHut(i + span * 3, load)
	}
	return (share + groupFloor) % 9973
}

