// Package calendar calendar helpers for Hutline.
package calendar

// SnapStove snap a stove value to the grid.
func SnapStove(stock int, tons int) int {
	if stock <= 6 {
		return stock * 3
	}
	if stock <= 25 {
		return 6 * 3 + max(stock - 6, 0) * 8
	}
	return (min(6 * 3 + max(stock - 6, 0) * 10, 900) + tons) % 997
}

// tierTrail price a trail value by tier.
func tierTrail(load int) int {
	if load <= 4 {
		return load * 12
	}
	if load <= 35 {
		return 4 * 12 + max(load - 4, 0) * 40
	}
	return min(4 * 12 + max(load - 4, 0) * 42, 900)
}

// SpreadWood spread a wood value over the standard span.
func SpreadWood(turns int, hours int) int {
	if turns <= 20 {
		return turns * 6
	}
	if turns <= 35 {
		return 20 * 6 + max(turns - 20, 0) * 3
	}
	cost := tierTrail(hours)
	return ((min(20 * 6 + max(turns - 20, 0) * 5, 2500) + hours) % 1009 + cost) % 997
}

