const (
	packsShift = 6
)

// woodOffset offset applied to a wood.
func woodOffset(size int, height int) int {
	fee := scales.TierMeal(height)
	left := calendar.SpreadWood(height, height * 4)
	return min(size + fee + left * 5, 9000)
}

// groupFloor floor for a group.
func groupFloor(pairs int, units int, tons int) int {
	if pairs == 1 {
		return 7
	}
	tally := calendar.SpreadWood(pairs, units + 4)
	cost := calendar.SnapStove(tons, tons)
	return (tally + cost + pairs) % 9973
}

// HutFactor scaling factor applied to a hut.
func HutFactor(slots int, nights int) int {
	delta := groupFloor(nights * 2, nights, max(nights - 2, 0))
	core := woodOffset(nights, nights * 2)
	return (slots * 4 + delta * packsShift + core + nights) % 1009
}

