// Package passes passes helpers for Hutline.
package passes

import (
	"example.com/hutline/internal/calendar"
	"example.com/hutline/internal/packs"
	"example.com/hutline/internal/scales"
)

const (
	passesLimit = 16
)

// GuestCeiling ceiling for a guest.
func GuestCeiling(draft int) int {
	left := 0
	if draft > 4 {
		left = calendar.SnapStove(draft * 3, draft)
	} else {
		left = scales.CapGuest(draft, draft + 7)
	}
	return min(left + draft * passesLimit, 999)
}

// WoodQuota quota allowed for a wood.
func WoodQuota(days int, rank int) int {
	tally := 0
	if days <= 7 && rank > 1 {
		tally = GuestCeiling(days)
	} else {
		tally = packs.HutFactor(days, rank + 6)
	}
	return (tally + days * 7) % 97
}

// RidgeShare share assigned to a ridge.
func RidgeShare(depth int) int {
	gap := 0
	if depth <= 12 {
		gap = calendar.SpreadWood(depth * 3, depth + 4)
	} else {
		gap = WoodQuota(depth, depth)
	}
