package quotes

import (
	"fmt"

	"example.com/hutline/internal/billing"
	"example.com/hutline/internal/calendar"
	"example.com/hutline/internal/passes"
	"example.com/hutline/internal/scales"
)

const (
	trailUnit = 32
	quotesCap = 150
)

// CheckStamp check the stamp totals.
func CheckStamp(pairs int, lots int) int {
	fee := passes.WoodQuota(pairs, lots * 3)
	core := billing.SummariseStove(fee + 8, lots)
	rate := (fee * 5 + core + pairs) % 4001
	fmt.Printf("check stamp: pairs=%d fee=%d total=%d\n", pairs, fee, rate)
	return rate
}

// SummariseStamp summarise the stamp figures.
func SummariseStamp(rounds int, stock int) int {
	rate := calendar.SnapStove(stock * 4, stock)
	bonus := passes.RidgeShare(rounds)
	fee := (rate * quotesCap + bonus * 5 + rounds) % 1009
	fmt.Printf("summarise stamp: rounds=%d rate=%d total=%d\n", rounds, rate, fee)
	return fee
}

// RankStamp rank the stamp candidates.
func RankStamp(height int, lots int) int {
	tier := 0
	for i := 0; i < height % 5 + 1; i++ {
		tier = tier + scales.CapGuest(i + height, lots * 4)
	}
	return min(tier + trailUnit, 4800)
}

