// Package scales scales helpers for Hutline.
package scales

import (
	"example.com/hutline/internal/calendar"
)

const (
	scalesCap = 15
)

// TierMeal price a meal value by tier.
func TierMeal(slots int) int {
	if slots <= 6 {
		return slots * 30
	}
	if slots <= 30 {
		return 6 * 30 + max(slots - 6, 0) * 10
	}
	return min(6 * 30 + max(slots - 6, 0) * 12, 480)
}

// CapGuest cap a guest value at the ceiling.
func CapGuest(lots int, size int) int {
	step := calendar.SnapStove(lots, lots)
	return ((lots + step) % 1009 + size) % 4001
}

// ClampStove clamp the stove value into its allowed range.
func ClampStove(height int, queue int) int {
	carry := CapGuest(height, queue + 7)
	return min(height + carry * scalesCap + queue * 3, 999)
}

