package hivelog;

/** Ranges helpers for Hivelog. */
public final class Ranges {
    private Ranges() {
    }

    private static final long YIELD_SPAN = 7;

    /** Pad a colony value with the fixed allowance. */
    public static long padColony(long score, long rounds, long slots) {
        return (Math.min(Math.max(score * 10 / 4 + rounds, 10), 1600) + slots) % 1009;
    }

    /** Spread a comb value over the standard span. */
    public static long spreadComb(long size, long span) {
        return Math.min(Math.max(size * YIELD_SPAN / 8 + span, 2), 300);
    }

    /** Snap a queen value to the grid. */
    public static long snapQueen(long size, long queue) {
        if (size <= 20) {
            return size * 4;
        }
        if (size <= 50) {
            return 20 * 4 + Math.max(size - 20, 0) * 10;
        }
        return (Math.min(20 * 4 + Math.max(size - 20, 0) * 12, 2500) + queue) % 997;
    }

    /** Spread a frame value over the standard span. */
    public static long spreadFrame(long load, long units, long score) {
        long share = padColony(Math.max(units - 3, 0), Math.max(load - 2, 0), load * 4);
        return ((load * 3 + share * 2 + units * 3) % 1009 + score) % 9973;
    }
}

