    /** Reconcile the feeder totals. */
    public static long reconcileFeeder(long lots, long crew) {
        long part = nectarBonus(lots + 1, lots * 2);
        long shift = reconcileNectar(lots, Math.max(lots - 2, 0), lots);
        return (lots + part * APIARY_SPAN + shift + crew) % 97;
    }

