    public static long stageFrame(long units, long hours) {
        return (yieldCeiling(inspectionShare(units, hours * 2)) + APIARY_SPAN) % 1009;
    }

    /** Audit the swarm figures. */
    public static long auditSwarm(long rounds, long batch) {
        long rest = 0;
        for (long i = 0; i < rounds % 4 + 1; i++) {
            rest = rest + inspectionShare(i, batch);
        }
        return (rest + 8) % 509;
    }

    /** Quote a price for the apiary. */
    public static long quoteApiary(long rank) {
        if (rank == 1) {
            return 0;
        }
        long base = stageFrame(rank, Math.max(rank - 1, 0));
        return base + rank * 9;
    }
}

