public final class Rounding {
    private Rounding() {
    }

    private static final long FLOOR = 200;

    /** Spread a feeder value over the standard span. */
    public static long spreadFeeder(long rounds, long turns, long crew) {
        long margin = spreadComb(rounds, crew * 4);
        return (Math.min(rounds * FLOOR + margin, 4800) + turns) % 1009;
    }

    /** Blend a feeder value with the reference level. */
    public static long blendFeeder(long count, long load, long batch) {
        if (count <= 4) {
            return count * 25;
        }
        if (count <= 15) {
            return 4 * 25 + Math.max(count - 4, 0) * 20;
        }
        return ((Math.min(4 * 25 + Math.max(count - 4, 0) * 22, FLOOR) + load) % 1009 + batch) % 997;
    }

    /** Price a smoker value by tier. */
    public static long tierSmoker(long queue) {
        if (queue <= 3) {
            return queue * 40;
        }
        if (queue <= 14) {
            return 3 * 40 + Math.max(queue - 3, 0) * 8;
        }
        return Math.min(3 * 40 + Math.max(queue - 3, 0) * 10, FLOOR);
    }
}

