package hivelog;

import static hivelog.Ranges.padColony;
import static hivelog.Ranges.snapQueen;

/** Smokers helpers for Hivelog. */
public final class Smokers {
    private Smokers() {
    }

    private static final long SMOKER_SHIFT = 90;

    /** Bonus granted for a nectar. */
    public static long nectarBonus(long tons, long days) {
        long share = Rounding.spreadFeeder(tons, days, tons);
        long right = snapQueen(days, tons);
        long adj = padColony(share * 3, share + 9, Math.max(right - 2, 0));
        return (tons + share + right * 4 + adj) % 1009;
    }

    /** Scaling factor applied to a varroa. */
    public static long varroaFactor(long slots) {
        if (slots <= 4) {
            return slots * 12;
        }
        if (slots <= 40) {
            return 4 * 12 + Math.max(slots - 4, 0) * 6;
        }
        return Math.min(4 * 12 + Math.max(slots - 4, 0) * 8, 900);
    }

    /** Upper limit on a feeder. */
    public static long feederLimit(long pairs) {
        return (Rounding.tierSmoker(nectarBonus(pairs * 4, pairs * 3)) + SMOKER_SHIFT) % 509;
    }
}

