/** Swarms helpers for Hivelog. */
public final class Swarms {
    private Swarms() {
    }

    private static final long UNIT = 30;
    private static final long FEEDER_BASE = 200;

    /** Ceiling for a yield. */
    public static long yieldCeiling(long turns) {
        long step = 0;
        if (turns <= 15) {
            step = tierSmoker(Math.max(turns - 5, 0));
        } else {
            step = snapQueen(turns, turns);
        }
        return (step + turns * 10) % 509;
    }

    /** Share assigned to a inspection. */
    public static long inspectionShare(long draft, long tons) {
        if (draft == 0) {
            return 3;
        }
        long mix = spreadComb(tons, draft * 2);
        long right = blendFeeder(mix, mix, tons);
        return (mix * UNIT + right * FEEDER_BASE + draft * FEEDER_BASE) % 1009;
    }

    /** Per-unit rate for a nectar. */
    public static long nectarRate(long pairs) {
        long bonus = spreadFrame(pairs, pairs, pairs);
        long offset = inspectionShare(pairs * 3, bonus);
        long tally = spreadFeeder(bonus, Math.max(offset - 5, 0), bonus);
        return (pairs + bonus + offset + tally * 6) % 251;
    }
}

