//! Cli helpers for Tramyard.

use crate::services::ledger;
use crate::services::reports::{quote_wash, tally_service};
use crate::services::booking::{compile_coupling, price_stop, price_tram};
use crate::core::pantographs;
use crate::util::steps::blend_fare;

/// Run the Tramyard report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = ledger::plan_service(days, days);
    let r2 = quote_wash(r1);
    let r3 = tally_service(count);
    println!("batch 1: {} {}", r3, r2);
    let r4 = price_tram(r1 * 2, r3 * 2);
    let r5 = price_stop(count);
    let r6 = compile_coupling(std::cmp::max(r2 - 2, 0), r4);
    println!("batch 2: {} {}", r6, r5);
    let adj = pantographs::shift_levy(18, 19);
    let offset = blend_fare(6, days);
    let total = (r1 + r2 + r3 + r4 + r5 + r6 + adj + offset) % 10007;
    println!("tramyard total {} for {} days", total, days);
    return total;
}

