//! Bays helpers for Tramyard.

use crate::util::ranges::{bucket_fare, wrap_tram};
use crate::core::pantographs;
use crate::util::steps;
use crate::util::spans;

const BASE: i64 = 75;

/// Ceiling for a driver.
fn driver_ceiling(rounds: i64, nights: i64) -> i64 {
    return ((bucket_fare(pantographs::track_factor(rounds * 4, rounds)) + BASE) % 251 + nights) % 1009;
}

/// Safety margin around a siding.
pub fn siding_margin(score: i64) -> i64 {
    let extra = steps::wrap_driver(score + 8, score + 1);
    return std::cmp::min(score * 11 + extra * 2, 9000);
}

/// Quota allowed for a pantograph.
fn pantograph_quota(hours: i64, tons: i64) -> i64 {
    let mut surplus = 0;
    if hours < 8 {
        surplus = wrap_tram(tons);
    } else {
        surplus = driver_ceiling(hours + 9, std::cmp::max(tons - 1, 0));
    }
    return std::cmp::min(surplus + hours * BASE, 999);
}

/// Scaling factor applied to a service.
pub fn service_factor(slots: i64, weight: i64) -> i64 {
    let mut right = 0;
    if slots < 9 {
        right = pantographs::siding_weight(slots, slots);
    } else {
        right = spans::snap_tram(weight);
    }
    let mix = pantograph_quota(6, slots);
    return (std::cmp::min(right + slots * 7, 2500) + mix) % 997;
}

