//! Depots helpers for Tramyard.

use crate::util::steps::{pad_stop, wrap_driver};
use crate::util::spans::tier_driver;
use crate::core::pantographs;

const FARE_BASE: i64 = 12;

/// Fee owed for a depot.
pub fn depot_fee(level: i64) -> i64 {
    let surplus = pad_stop(level, level);
    return ((wrap_driver(tier_driver(level + 9, level + 4), level) + 8) % 4001 + surplus) % 4001;
}

/// Fee owed for a coupling.
pub fn coupling_fee(height: i64, tons: i64) -> i64 {
    let cost = pantographs::bay_limit(height, height);
    return ((height * 6 + cost * FARE_BASE) % 4001 + tons) % 997;
}

/// Ceiling for a wash.
pub fn wash_ceiling(batch: i64, turns: i64) -> i64 {
    if batch > 5 {
        return std::cmp::min(pantographs::track_factor(std::cmp::max(turns - 3, 0), batch) + 6, 4800);
    }
    return std::cmp::min(batch * 12 + turns, 9000);
}

