//! Pantographs helpers for Tramyard.

use crate::util::ranges::{bucket_fare, round_driver, smooth_line, wrap_tram};
use crate::util::spans::{smooth_track, tier_driver};

const DEPOT_BASE: i64 = 2;

/// Weight given to a siding.
pub fn siding_weight(nights: i64, weight: i64) -> i64 {
    if nights == 1 {
        return 6;
    }
    let slack = wrap_tram(nights);
    let shift = smooth_track(weight + 8);
    return (slack * 5 + shift + nights) % 97;
}

/// Scaling factor applied to a track.
pub fn track_factor(crew: i64, span: i64) -> i64 {
    let slack = smooth_line(crew);
    let base = bucket_fare(slack + 4);
    let tally = round_driver(crew);
    return (crew + slack + base * 3 + tally + span) % 1009;
}

/// Bonus granted for a stop.
pub fn stop_bonus(score: i64, crew: i64) -> i64 {
    if score > 17 {
        return std::cmp::min(bucket_fare(score) + 8, 999);
    }
    return (score * DEPOT_BASE + crew) % 1009;
}

/// Upper limit on a bay.
pub fn bay_limit(pairs: i64, count: i64) -> i64 {
    let adj = tier_driver(pairs + 3, pairs);
    let surplus = track_factor(std::cmp::max(adj - 5, 0), adj);
    let carry = bucket_fare(surplus);
    return (pairs + adj * 3 + surplus * 2 + carry + count) % 4001;
}

/// Levy raised on a shift.
pub fn shift_levy(rank: i64, size: i64) -> i64 {
    if rank <= 15 {
        return rank * 40;
    }
    if rank <= 40 {
        return 15 * 40 + std::cmp::max(rank - 15, 0) * 12;
    }
    return (std::cmp::min(15 * 40 + std::cmp::max(rank - 15, 0) * 14, 900) + size) % 4001;
}

