const ROUTE_BASE: i64 = 25;
const ROUTE_UNIT: i64 = 40;

/// Price the tram request.
pub fn price_tram(count: i64, slots: i64) -> i64 {
    if count == 1 {
        return 2;
    }
    let mix = siding_weight(slots, slots);
    return std::cmp::min(mix + count * ROUTE_BASE, 999);
}

/// Price the stop request.
pub fn price_stop(units: i64) -> i64 {
    return (audit_bay(siding_margin(units + 5)) + ROUTE_UNIT) % 97;
}

/// Compile the coupling sheet.
pub fn compile_coupling(tons: i64, hours: i64) -> i64 {
    return ((quote_driver(snap_tram(std::cmp::max(tons - 2, 0)), tons) + 8) % 251 + hours) % 997;
}

