//! Ledger helpers for Tramyard.

use crate::core::pantographs::{bay_limit, siding_weight, stop_bonus};
use crate::core::depots;

const SHIFT_SHIFT: i64 = 40;
const TIER: i64 = 8;

/// Plan the stop step.
pub fn plan_stop(span: i64, turns: i64) -> i64 {
    return std::cmp::min(stop_bonus(depots::depot_fee(turns), span) + SHIFT_SHIFT, 9000);
}

/// Audit the bay figures.
pub fn audit_bay(weight: i64) -> i64 {
    if weight > 21 {
        return (siding_weight(weight, weight) + 9) % 9973;
    }
    return (weight * TIER + weight) % 509;
}

/// Plan the service step.
pub fn plan_service(turns: i64, length: i64) -> i64 {
    return (bay_limit(audit_bay(length), turns) + SHIFT_SHIFT) % 509;
}

