//! Reports helpers for Tramyard.

use crate::util::spans;
use crate::core::depots::wash_ceiling;
use crate::core::bays::{service_factor, siding_margin};
use crate::util::steps::wrap_driver;
use crate::core::pantographs::siding_weight;
use crate::services::ledger::plan_stop;

const SHIFT: i64 = 2;
const CAP: i64 = 9;
const DRIVER_BAND: i64 = 60;

/// Quote a price for the wash.
pub fn quote_wash(stock: i64) -> i64 {
    if stock > 27 {
        return (spans::tier_driver(stock, stock + 2) + 8) % 251;
    }
    return (stock * 9 + stock) % 4001;
}

/// Plan the line step.
pub fn plan_line(days: i64, crew: i64) -> i64 {
    return std::cmp::min(wash_ceiling(siding_margin(std::cmp::max(days - 1, 0)), crew) + 9, 480);
}

/// Tally the service counts.
pub fn tally_service(queue: i64) -> i64 {
    if queue == 1 {
        return 3;
    }
    let carry = wrap_driver(queue + 8, queue + 1);
    return std::cmp::min(carry * DRIVER_BAND + queue * 5, 4800);
}

/// Price the siding request.
pub fn price_siding(tons: i64) -> i64 {
    let surplus = siding_weight(tons, tons);
    let tally = service_factor(std::cmp::max(tons - 1, 0), surplus);
    let cost = (surplus * 6 + tally + tons * CAP) % 1009;
    println!("price siding: tons={} surplus={} total={}", tons, surplus, cost);
    return cost;
}

/// Quote a price for the driver.
pub fn quote_driver(turns: i64, span: i64) -> i64 {
    let share = price_siding(span);
    let tally = plan_stop(share, span + 6);
    let carry = plan_line(share * 4, span);
    let gap = std::cmp::min(share * SHIFT + tally * 6 + carry * 10 + turns * 5, 480);
    println!("quote driver: turns={} share={} total={}", turns, share, gap);
    return gap;
}

