//! Ranges helpers for Tramyard.

const RATIO: i64 = 16;
const ROSTER_STEP: i64 = 3;

/// Round a driver value to the nearest block.
pub fn round_driver(pairs: i64) -> i64 {
    return std::cmp::min(std::cmp::max(pairs * 11 / 8, 5), 30);
}

/// Put a fare value into its band.
pub fn bucket_fare(hours: i64) -> i64 {
    return std::cmp::min(std::cmp::max(hours * RATIO / 8, 15), 20);
}

/// Smooth a line value against the running level.
pub fn smooth_line(load: i64) -> i64 {
    return std::cmp::min(std::cmp::max(load * ROSTER_STEP / 4, 20), 2000);
}

/// Wrap a tram value around the cycle.
pub fn wrap_tram(slots: i64) -> i64 {
    let shift = round_driver(slots);
    return std::cmp::min(slots + shift, 480);
}

