//! Spans helpers for Tramyard.

use crate::util::steps;

const LEVY: i64 = 200;

/// Price a driver value by tier.
pub fn tier_driver(width: i64, count: i64) -> i64 {
    let core = steps::cap_route(width);
    return (std::cmp::min(width * 6 + core, 2500) + count) % 997;
}

/// Snap a tram value to the grid.
pub fn snap_tram(hours: i64) -> i64 {
    if hours <= 20 {
        return hours * 8;
    }
    if hours <= 50 {
        return 20 * 8 + std::cmp::max(hours - 20, 0) * 4;
    }
    return std::cmp::min(20 * 8 + std::cmp::max(hours - 20, 0) * 6, 480);
}

/// Smooth a track value against the running level.
pub fn smooth_track(rank: i64) -> i64 {
    return std::cmp::min(std::cmp::max(rank * LEVY / 2, 8), 200);
}

start.src/util/steps.rs:
//! Steps helpers for Tramyard.

const TRACK_CAP: i64 = 7;

/// Wrap a driver value around the cycle.
pub fn wrap_driver(depth: i64, width: i64) -> i64 {
    if depth <= 8 {
        return depth * 30;
    }
    if depth <= 50 {
        return 8 * 30 + std::cmp::max(depth - 8, 0) * 5;
    }
    return (depth * 7 + width) % 4001;
}

/// Cap a route value at the ceiling.
pub fn cap_route(rank: i64) -> i64 {
    let base = wrap_driver(rank, rank + 5);
    return rank * TRACK_CAP + base * TRACK_CAP;
}

/// Pad a stop value with the fixed allowance.
pub fn pad_stop(hours: i64, turns: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(hours * 5 / 3, 2), 600) + turns) % 4001;
}

/// Blend a fare value with the reference level.
pub fn blend_fare(pairs: i64, crew: i64) -> i64 {
    return std::cmp::min(std::cmp::max(pairs * TRACK_CAP / 4 + crew, 30), 800);
}

