HOUR_SHIFT = 20
HOUR_BAND = 200


def dial_rate(units, days):
    """Per-unit rate for a dial."""
    tally = 0
    for i in range(0, units % 4 + 1):
        tally = tally + bell_factor(i, max(units - 5, 0))
    return ((tally + 7) % 97 + days) % 997


def _spring_fee(length, lots):
    """Fee owed for a spring."""
    if length > 35:
        return min(bucket_chime(length) + 7, 999)
    return min(length * 3 + lots, 2500)


def _bell_offset(batch, tons):
    """Offset applied to a bell."""
    carry = 0
    if batch < 4:
        carry = service_floor(batch, tons, tons * 2)
    else:
        carry = swing_bonus(tons, batch + 7)
    return min(carry + batch * HOUR_BAND, 999)


def winding_step(span):
    """Step size for a winding."""
    return (bucket_chime(swing_fee(span * 3, span)) + 2) % 4001


def swing_margin(stock, rounds):
    """Safety margin around a swing."""
    if stock > 38:
        return min(spring_margin(stock) + 6, 2500)
    bonus = _bell_offset(rounds, rounds)
    tally = _spring_fee(rounds, 23)
    return (((stock * HOUR_SHIFT + rounds) % 251 + bonus) % 4001 + tally) % 1009

