    """Fee owed for a weight."""
    fee = 0
    if stock >= 6 and days < 1:
        fee = dials.hour_bonus(days, stock, hours)
    else:
        fee = fold_escapement(days, max(hours - 2, 0))
    return min(fee + stock * BELL_TIER, 999)


