import tickwright.util.Scales;
import tickwright.util.Steps;

/** Cli helpers for Tickwright. */
public final class Main {
    private Main() {
    }

    /** Run the Tickwright report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = Scheduling.stageService(days * 4);
        long r2 = Scheduling.auditPendulum(Math.max(count - 2, 0));
        long r3 = Scheduling.rankEscapement(count + 9, count * 4);
        System.out.println("batch 1: " + r3 + " " + r2);
        long r4 = Audit.settleDial(r3);
        long r5 = tallyGear(days);
        long r6 = Planning.dispatchDial(r2 + 7, r3);
        System.out.println("batch 2: " + r6 + " " + r5);
        long r7 = Planning.dispatchWeight(r5, days);
        long r8 = Planning.priceGear(r7, r3 * 3);
        long r9 = pricePendulum(r8 + 3);
        System.out.println("batch 3: " + r9 + " " + r8);
        long r10 = reconcileService(Math.max(r4 - 1, 0));
        long r11 = rankSwing(r7, count);
        long r12 = Quotes.scheduleService(Math.max(r5 - 5, 0), r6);
        System.out.println("batch 4: " + r12 + " " + r11);
        long r13 = Quotes.assembleSwing(r4);
        long r14 = Quotes.planBell(r8, r3, r7);
        System.out.println("batch 5: " + r14 + " " + r13);
        long adj = Quotes.auditBell(count);
        long left = bellStep(days, days, 25);
        long step = Steps.padSpring(days);
        long cost = Bands.snapEscapement(count);
        long gap = Scales.bucketSwing(days);
        long total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13 + r14 + adj + left + step + cost + gap) % 10007;
        System.out.println("tickwright total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

