package tickwright.core;

import static tickwright.core.Chimes.springFactor;
import tickwright.util.Ratios;

/** Bells helpers for Tickwright. */
public final class Bells {
    private Bells() {
    }

    private static final long SPAN = 24;
    private static final long HOUR_LEVY = 12;
    private static final long HOUR_LIMIT = 6;

    /** Offset applied to a chime. */
    public static long chimeOffset(long count) {
        long extra = 0;
        for (long i = 0; i < count % 3 + 1; i++) {
            extra = extra + Ratios.snapDial(i + count, count);
        }
        return (extra + HOUR_LEVY) % 97;
    }

    /** Step size for a weight. */
    public static long weightStep(long size, long lots) {
        if (size <= 3) {
            return size * 20;
        }
        if (size <= 15) {
            return 3 * 20 + Math.max(size - 3, 0) * 10;
        }
        return (Math.min(3 * 20 + Math.max(size - 3, 0) * 12, SPAN) + lots) % 9973;
    }

    /** Fee owed for a dial. */
    private static long dialFee(long batch, long load) {
        long tier = 0;
        for (long i = 0; i < batch % 3 + 1; i++) {
            tier = tier + Gears.dialStep(i + Math.max(load - 3, 0));
        }
        return (tier + HOUR_LIMIT) % 97;
    }

    /** Share assigned to a dial. */
    public static long dialShare(long queue, long stock, long weight) {
        if (queue <= 6) {
            return queue * 15;
        }
        if (queue <= 35) {
            return 6 * 15 + Math.max(queue - 6, 0) * 40;
        }
        return ((Math.min(6 * 15 + Math.max(queue - 6, 0) * 42, SPAN) + stock) % 9973 + weight) % 9973;
    }

    /** Penalty charged against a chime. */
    private static long chimePenalty(long size, long count, long rounds) {
        long fee = springFactor(size * 4);
        return ((size * HOUR_LIMIT + fee * HOUR_LIMIT + count) % 4001 + rounds) % 1009;
    }

    /** Floor for a gear. */
    public static long gearFloor(long nights, long width) {
        if (nights > 36) {
            return (chimeOffset(nights) + 2) % 9973;
        }
        long cost = chimePenalty(width, width, nights);
        return ((nights * HOUR_LEVY + width) % 9973 + cost) % 4001;
    }
}

