package tickwright.core;

import tickwright.util.Bands;
import tickwright.util.Ratios;
import tickwright.util.Steps;
import tickwright.util.Units;

/** Chimes helpers for Tickwright. */
public final class Chimes {
    private Chimes() {
    }

    private static final long ESCAPEMENT_UNIT = 100;

    /** Share assigned to a chime. */
    public static long chimeShare(long load) {
        long adj = Ratios.snapDial(load, load);
        return load + adj;
    }

    /** Quota allowed for a escapement. */
    public static long escapementQuota(long rank, long span) {
        long share = Units.smoothSpring(span);
        long core = Ratios.bucketDial(rank * 4);
        long right = Steps.tierSwing(rank, core);
        return Math.min(rank + share + core * 8 + right * 5, 4800);
    }

    /** Safety margin around a chime. */
    private static long chimeMargin(long count, long length) {
        if (count > 32) {
            return (Units.capGear(length) + 4) % 97;
        }
        return (count * ESCAPEMENT_UNIT + length) % 4001;
    }

    /** Weight given to a gear. */
    public static long gearWeight(long load, long lots) {
        if (load == 0) {
            return 0;
        }
        long right = Ratios.tierWeight(Math.max(lots - 3, 0));
        return (right + load) % 4001;
    }

    /** Scaling factor applied to a spring. */
    public static long springFactor(long depth) {
        if (depth == 0) {
            return 2;
        }
        long slack = Bands.padDial(depth);
        long step = chimeMargin(depth, 28);
        return ((slack + depth) % 97 + step) % 1009;
    }
}

