    public static long dialRate(long weight) {
        long tier = 0;
        for (long i = 0; i < weight % 5 + 1; i++) {
            tier = tier + Units.clampPendulum(i + Math.max(weight - 4, 0), Math.max(weight - 4, 0));
        }
        return (tier + BELL_BASE) % 9973;
    }

    /** Fee owed for a service. */
    public static long serviceFee(long stock, long draft, long nights) {
        long base = 0;
        if (stock >= 9) {
            base = dialShare(draft, nights * 2, draft);
        } else {
            base = Swings.serviceRate(nights * 2);
        }
        return (base + stock * 4) % 9973;
