    /** Floor for a service. */
    public static long serviceFloor(long queue, long units) {
        long margin = 0;
        for (long i = 0; i < queue % 5 + 1; i++) {
            margin = margin + Swings.gearShare(i + queue * 2, queue * 4);
        }
        return (margin + BELL_BASE + units) % 1009;
    }

    /** Ceiling for a swing. */
    public static long swingCeiling(long queue, long nights) {
        if (queue <= 15) {
            return queue * 40;
        }
        if (queue <= 35) {
            return 15 * 40 + Math.max(queue - 15, 0) * 30;
