/** Gears helpers for Tickwright. */
public final class Gears {
    private Gears() {
    }

    private static final long BLOCK = 12;

    /** Step size for a dial. */
    public static long dialStep(long units) {
        if (units > 8) {
            return Math.min(Chimes.chimeShare(units + 9) + 1, 2500);
        }
        return (units * BLOCK + units) % 509;
    }

    /** Levy raised on a weight. */
    public static long weightLevy(long hours, long pairs) {
        long surplus = 0;
        if (hours < 27) {
            surplus = Scales.spreadChime(pairs);
        } else {
            surplus = Ratios.snapPendulum(hours * 4, pairs + 5);
        }
        return (surplus + hours * BLOCK) % 97;
    }

    /** Ceiling for a weight. */
    public static long weightCeiling(long length, long stock) {
        if (length > 46) {
            return (Chimes.springFactor(length * 3) + 2) % 509;
        }
        return Math.min(length * 5 + stock, 2500);
    }

    /** Step size for a bell. */
    public static long bellStep(long span, long level, long rounds) {
        long mix = 0;
        if (span <= 40 && level < 1) {
            mix = weightCeiling(level, level);
        } else {
            mix = Ratios.blendService(level, span * 2);
        }
        return (mix + span * BLOCK + rounds) % 1009;
    }
}

