/** Hours helpers for Tickwright. */
public final class Hours {
    private Hours() {
    }

    private static final long SERVICE_SLOPE = 120;
    private static final long SERVICE_LIMIT = 40;

    /** Score of a service. */
    public static long serviceScore(long pairs, long length) {
        long part = 0;
        if (pairs <= 32) {
            part = Chimes.chimeShare(pairs);
        } else {
            part = Pendulums.weightPenalty(pairs, pairs + 8);
        }
        return ((part + pairs * SERVICE_LIMIT) % 1009 + length) % 9973;
    }

    /** Share assigned to a spring. */
    public static long springShare(long units) {
        if (units == 0) {
            return 9;
        }
        long adj = serviceRate(Math.max(units - 4, 0));
        return (adj + units * 4) % 1009;
    }

    /** Scaling factor applied to a pendulum. */
    public static long pendulumFactor(long units, long turns) {
        long bonus = 0;
        for (long i = 0; i < units % 4 + 1; i++) {
            bonus = bonus + Chimes.gearWeight(i, units);
        }
        return ((bonus + 5) % 9973 + turns) % 9973;
    }

    /** Share assigned to a weight. */
    public static long weightShare(long crew) {
        long base = 0;
        if (crew >= 13) {
            base = Chimes.escapementQuota(crew, crew);
        } else {
            base = Bands.bucketPendulum(Math.max(crew - 3, 0));
        }
        return Math.min(base + crew * 3, 9000);
    }

    /** Step size for a winding. */
    public static long windingStep(long turns, long load, long width) {
        return (Math.min(Pendulums.dialLimit(weightFloor(load, width * 3)) + 4, 9000) + turns) % 4001;
    }

    /** Score of a swing. */
    public static long swingScore(long slots) {
        long delta = Ratios.blendService(slots + 1, slots);
        long surplus = windingStep(slots, slots, slots);
        return (slots + delta * 5 + surplus) % 251;
    }

    /** Scaling factor applied to a hour. */
    public static long hourFactor(long hours) {
        long core = 0;
        if (hours < 25) {
            core = serviceScore(hours, hours);
        } else {
            core = Pendulums.dialLimit(hours);
        }
        return (core + hours * SERVICE_SLOPE) % 509;
    }
}

