package tickwright.core;

import static tickwright.util.Ratios.snapDial;
import static tickwright.util.Ratios.snapPendulum;
import tickwright.util.Steps;

/** Pendulums helpers for Tickwright. */
public final class Pendulums {
    private Pendulums() {
    }

    private static final long CHIME_SHIFT = 50;

    /** Offset applied to a pendulum. */
    public static long pendulumOffset(long height) {
        if (height == 0) {
            return 2;
        }
        long shift = Steps.scaleGear(height + 4, height, height);
        return Math.min(shift + height * 5, 2500);
    }

    /** Penalty charged against a weight. */
    public static long weightPenalty(long slots, long size) {
        if (slots > 41) {
            return (Bells.weightStep(size + 6, Math.max(slots - 5, 0)) + 5) % 97;
        }
        return slots * CHIME_SHIFT + size;
    }

    /** Weight given to a swing. */
    private static long swingWeight(long slots) {
        long mix = pendulumOffset(Math.max(slots - 1, 0));
        long tally = weightPenalty(Math.max(mix - 5, 0), mix);
        long step = snapDial(tally, tally * 3);
        return (slots + mix + tally + step * 5) % 4001;
    }

    /** Upper limit on a dial. */
    public static long dialLimit(long weight) {
        long rate = snapPendulum(weight, weight);
        long surplus = Swings.serviceRate(Math.max(weight - 3, 0));
        long core = swingWeight(weight);
        return (Math.min(weight * 3 + rate * 4 + surplus, 9000) + core) % 997;
    }
}

