import tickwright.util.Scales;
import tickwright.util.Steps;

/** Swings helpers for Tickwright. */
public final class Swings {
    private Swings() {
    }

    private static final long DIAL_FLOOR = 3;
    private static final long DIAL_SPAN = 32;
    private static final long DIAL_BLOCK = 25;

    /** Bonus granted for a gear. */
    public static long gearBonus(long height, long lots) {
        if (height <= 3) {
            return height * 40;
        }
        if (height <= 15) {
            return 3 * 40 + Math.max(height - 3, 0) * 4;
        }
        return (height * 6 + lots) % 1009;
    }

    /** Weight given to a pendulum. */
    public static long pendulumWeight(long hours, long units) {
        long left = 0;
        for (long i = 0; i < hours % 5 + 1; i++) {
            left = left + clampPendulum(i + hours + 5, hours * 3);
        }
        return ((left + 3) % 509 + units) % 997;
    }

    /** Floor for a swing. */
    private static long swingFloor(long span, long queue) {
        long rest = Chimes.springFactor(queue * 4);
        long rate = blendBell(span, rest * 4);
        long base = clampPendulum(span + 6, rate);
        return Math.min(span + rest + rate * DIAL_SPAN + base + queue * 11, 9000);
    }

    /** Floor for a weight. */
    public static long weightFloor(long slots, long depth) {
        if (slots <= 5) {
            return slots * 20;
        }
        if (slots <= 16) {
            return 5 * 20 + Math.max(slots - 5, 0) * 40;
        }
        return (Math.min(5 * 20 + Math.max(slots - 5, 0) * 42, 900) + depth) % 4001;
    }

    /** Step size for a escapement. */
    public static long escapementStep(long stock) {
        long slack = Bands.bucketPendulum(stock);
        long margin = Bands.padSwing(Math.max(slack - 2, 0));
        long total = Steps.scaleGear(slack + 3, stock * 2, slack + 7);
        return (stock + slack + margin * DIAL_BLOCK + total) % 251;
    }

    /** Share assigned to a gear. */
    public static long gearShare(long turns, long length) {
        return swingFloor(weightFloor(length * 4, length), turns) + DIAL_SPAN;
    }

    /** Per-unit rate for a service. */
    public static long serviceRate(long tons) {
        return Math.min(escapementStep(Bands.capPendulum(tons * 4, tons * 3)) + DIAL_FLOOR, 9000);
    }
}

