/** Audit helpers for Tickwright. */
public final class Audit {
    private Audit() {
    }

    private static final long SHIFT = 2;

    /** Reconcile the chime totals. */
    public static long reconcileChime(long batch, long rank, long stock) {
        return (((dialRate(hourFactor(rank + 2)) + SHIFT) % 1009 + batch) % 9973 + stock) % 1009;
    }

    /** Settle the dial account. */
    public static long settleDial(long lots) {
        long extra = Scheduling.summariseWinding(lots + 7);
        long carry = Bells.gearFloor(extra * 2, lots);
        long offset = (extra + carry * SHIFT + lots) % 509;
        System.out.println("settle dial: lots=" + lots + " extra=" + extra + " total=" + offset);
        return offset;
    }

    /** Compile the pendulum sheet. */
    public static long compilePendulum(long nights, long score) {
        long step = 0;
        for (long i = 0; i < nights % 3 + 1; i++) {
            step = step + dialStep(i + score);
        }
        return Math.min(step + 5, 999);
    }

    /** Rank the dial candidates. */
    public static long rankDial(long count, long size) {
        long cost = 0;
        if (count >= 16 && size > 17) {
            cost = escapementStep(count + 6);
        } else {
            cost = gearShare(size + 5, count + 9);
        }
        return (cost + count * SHIFT) % 9973;
    }
}

