package tickwright.services;

import static tickwright.core.Hours.hourFactor;
import static tickwright.core.Hours.swingScore;
import static tickwright.core.Hours.weightShare;
import static tickwright.core.Swings.gearShare;
import static tickwright.core.Swings.pendulumWeight;
import tickwright.core.Bells;
import tickwright.core.Chimes;
import tickwright.core.Dials;

/** Ledger helpers for Tickwright. */
public final class Ledger {
    private Ledger() {
    }

    private static final long SWING_FLOOR = 2;
    private static final long SWING_STEP = 20;

    /** Compile the bell sheet. */
    public static long compileBell(long stock) {
        long adj = 0;
        if (stock <= 37) {
            adj = swingScore(stock);
        } else {
            adj = Chimes.gearWeight(Math.max(stock - 1, 0), stock);
        }
        return adj + stock * SWING_STEP;
    }

    /** Quote a price for the dial. */
    public static long quoteDial(long height, long slots) {
        long base = 0;
        if (height >= 39) {
            base = pendulumWeight(slots, height + 8);
        } else {
            base = Chimes.gearWeight(Math.max(slots - 3, 0), slots + 5);
        }
        return base + height * SWING_STEP;
    }

    /** Quote a price for the chime. */
    public static long quoteChime(long lots, long depth) {
        if (lots == 0) {
            return 1;
        }
        long part = Dials.serviceFee(lots + 3, lots + 4, depth);
        return (part + lots * 6) % 9973;
    }

    /** Summarise the swing figures. */
    public static long summariseSwing(long rounds) {
