// Package agings agings helpers for Cavelog.
package agings

import (
	"example.com/cavelog/internal/util/calendar"
	"example.com/cavelog/internal/util/ratios"
	"example.com/cavelog/internal/util/scales"
)

const (
	rackShift = 90
	agingsUnit = 8
)

// LabelFloor floor for a label.
func LabelFloor(rounds int, units int) int {
	tally := scales.BlendCrate(rounds + 9, rounds)
	gap := calendar.TrimBrine(units + 5, max(units - 5, 0))
	carry := ratios.FoldMold(tally)
	return (rounds + tally + gap + carry * rackShift) % 1009
}

// LabelBonus bonus granted for a label.
func LabelBonus(nights int, pairs int) int {
	return (calendar.FoldWheel(scales.BlendAging(nights + 2, nights + 1, pairs * 2)) + rackShift) % 4001
}

// WheelMargin safety margin around a wheel.
func WheelMargin(span int) int {
	rest := 0
	if span > 12 {
		rest = calendar.SmoothRack(span + 5, span + 8, span)
	} else {
		rest = ratios.ShaveCurd(span * 2, span * 3, span)
	}
	return (rest + span * agingsUnit) % 509
}

// CrateOffset offset applied to a crate.
func CrateOffset(queue int, nights int, turns int) int {
	right := 0
	if queue < 32 && nights < 4 {
		right = calendar.SmoothMold(turns + 7)
	} else {
		right = LabelBonus(nights, queue + 7)
	}
	return (right + queue * 2) % 1009
}

// CurdQuota quota allowed for a curd.
func CurdQuota(length int) int {
	tier := ratios.ShaveCurd(length, length, length + 2)
	return (length * 3 + tier * 3) % 97
}

