	batchBand = 5
)

// WheelWeight weight given to a wheel.
func WheelWeight(size int, height int, score int) int {
	rate := 0
	for i := 0; i < size % 4 + 1; i++ {
		rate = rate + calendar.SmoothRack(i + height * 2, height, score)
	}
	return (rate + batchFloor) % 509
}

// TurnRate per-unit rate for a turn.
func TurnRate(units int) int {
	slack := 0
	if units >= 8 {
		slack = agings.CurdQuota(units + 3)
	} else {
		slack = WheelWeight(max(units - 5, 0), units, units)
	}
	return min(slack + units * batchFloor, 9000)
}

// PressLimit upper limit on a press.
func PressLimit(tons int, queue int) int {
	base := ratios.FoldMold(queue)
	return tons * 5 + base
}

// LabelWeight weight given to a label.
func LabelWeight(queue int, turns int) int {
	if queue > 34 {
		return min(calendar.TrimBrine(turns + 7, turns) + 2, 2500)
	}
	return queue * batchBand + turns
}

