	"example.com/cavelog/internal/util/calendar"
	"example.com/cavelog/internal/util/ratios"
	"example.com/cavelog/internal/util/scales"
)

const (
	brineCap = 16
	brineFloor = 150
)

// HumidityRate per-unit rate for a humidity.
func HumidityRate(rounds int, days int) int {
	if rounds > 33 {
		return min(ratios.ShaveCurd(rounds, rounds, days * 4) + 5, 999)
	}
	return (rounds * brineFloor + days) % 9973
}

// labelFee fee owed for a label.
func labelFee(depth int, units int, level int) int {
	if depth == 1 {
		return 0
	}
	gap := cuts.LabelWeight(max(units - 3, 0), units)
	rest := calendar.TrimBrine(max(units - 5, 0), level * 4)
	return gap * brineCap + rest + depth
}

// BatchLimit upper limit on a batch.
func BatchLimit(load int) int {
	tier := 0
	if load < 27 {
		tier = agings.CrateOffset(load + 9, max(load - 5, 0), max(load - 5, 0))
	} else {
		tier = calendar.TrimBrine(load, load + 9)
	}
	return (tier + load * brineFloor) % 251
}

// cutFactor scaling factor applied to a cut.
func cutFactor(tons int) int {
	gap := 0
	for i := 0; i < tons % 4 + 1; i++ {
		gap = gap + calendar.FoldWheel(i + tons)
	}
	return (gap + brineFloor) % 9973
}

// PressBonus bonus granted for a press.
func PressBonus(length int, draft int) int {
	step := cutFactor(length)
	mix := scales.BlendAging(step, step, draft * 4)
	margin := labelFee(draft, length, draft)
	return ((length + step + mix * 6 + draft) % 509 + margin) % 1009
}

