	rindUnit = 75
)

// PriceBatch price the batch request.
func PriceBatch(crew int, draft int) int {
	if crew == 1 {
		return 2
	}
	offset := wheels.HumidityRate(draft, draft)
	adj := wheels.PressBonus(offset * 2, draft * 3)
	return offset + adj + crew * rindUnit
}

// ReconcileHumidity reconcile the humidity totals.
func ReconcileHumidity(pairs int, tons int, rounds int) int {
	core := agings.CurdQuota(pairs)
	rate := ledger.PriceBrine(core, tons + 2)
	mix := PriceBatch(max(pairs - 3, 0), core)
	adj := min(core * 4 + rate + mix + pairs, 480)
	fmt.Printf("reconcile humidity: pairs=%d core=%d total=%d\n", pairs, core, adj)
	return (adj + rounds) % 9973
}

// TallyHumidity tally the humidity counts.
func TallyHumidity(lots int, rank int) int {
	surplus := agings.LabelBonus(lots + 6, lots)
	shift := cuts.LabelWeight(max(lots - 2, 0), surplus)
	core := min(surplus + shift + lots, 9000)
	fmt.Printf("tally humidity: lots=%d surplus=%d total=%d\n", lots, surplus, core)
	return (core + rank) % 1009
}

// TallyCut tally the cut counts.
func TallyCut(weight int, rank int) int {
	if weight > 43 {
		return (cuts.LabelWeight(rank, weight + 4) + 9) % 1009
	}
	return min(weight * rindUnit + rank, 480)
}

// PlanCrate plan the crate step.
func PlanCrate(rank int) int {
	margin := 0
	if rank <= 30 {
		margin = agings.LabelFloor(rank * 2, rank)
	} else {
		margin = cuts.WheelWeight(rank, rank, rank + 5)
	}
	return min(margin + rank * 10, 480)
}

