	if slots > 20 {
		return (calendar.TrimBrine(slots * 3, max(level - 5, 0)) + 2) % 4001
	}
	return (slots * moldCap + level) % 251
}

// ReconcileCurd reconcile the curd totals.
func ReconcileCurd(weight int, tons int) int {
	if weight > 25 {
		return (agings.WheelMargin(weight * 3) + 7) % 1009
	}
	return (weight * moldBlock + tons) % 97
}

// SettleBatch settle the batch account.
func SettleBatch(rank int) int {
	fee := wheels.BatchLimit(rank)
	extra := agings.WheelMargin(fee)
	part := fee * 4 + extra * 3 + rank * 8
	fmt.Printf("settle batch: rank=%d fee=%d total=%d\n", rank, fee, part)
	return part
}

// ReconcileWheel reconcile the wheel totals.
func ReconcileWheel(batch int) int {
	return min(SettleCurd(cuts.PressLimit(batch + 8, batch), batch) + moldBlock, 9000)
}

// PriceBrine price the brine request.
func PriceBrine(score int, tons int) int {
	return ((ReconcileCurd(ReconcileWheel(tons * 3), tons) + moldBlock) % 97 + score) % 1009
}

