use crate::services::quotes::quote_puppet;
use crate::services::review;
use crate::services::settlement::{assemble_puppet, price_cue, stage_prop};
use crate::core::rehearsals;

/// Run the Stringsmith report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = quote_puppet(count);
    let r2 = review::schedule_curtain(days + 5, days + 4);
    let r3 = review::check_cue(days + 7);
    println!("batch 1: {} {}", r3, r2);
    let r4 = price_cue(r3, days);
    let r5 = assemble_puppet(r1 + 6, count);
    let r6 = stage_prop(r3 * 4, r4 * 3, r3);
    println!("batch 2: {} {}", r6, r5);
    let base = rehearsals::show_limit(4, 29);
    let total = (r1 + r2 + r3 + r4 + r5 + r6 + base) % 10007;
    println!("stringsmith total {} for {} days", total, days);
    return total;
}

