//! Props helpers for Stringsmith.

use crate::util::limits::clamp_cue;

const ACT_RATIO: i64 = 10;
const CAP: i64 = 40;

/// Upper limit on a cue.
pub fn cue_limit(lots: i64, crew: i64) -> i64 {
    let mut margin = 0;
    for i in 0..lots % 3 + 1 {
        margin = margin + clamp_cue(i + crew, lots);
    }
    return std::cmp::min(margin + ACT_RATIO, 480);
}

/// Weight given to a puppet.
pub fn puppet_weight(count: i64, days: i64) -> i64 {
    if count > 27 {
        return (cue_limit(std::cmp::max(count - 4, 0), days + 5) + 4) % 9973;
    }
    return count * CAP + days;
}

/// Ceiling for a curtain.
pub fn curtain_ceiling(depth: i64) -> i64 {
    if depth <= 8 {
        return depth * 10;
    }
    if depth <= 40 {
        return 8 * 10 + std::cmp::max(depth - 8, 0) * 4;
    }
    return std::cmp::min(8 * 10 + std::cmp::max(depth - 8, 0) * 6, 2500);
}

/// Ceiling for a lamp.
pub fn lamp_ceiling(nights: i64) -> i64 {
    if nights <= 4 {
        return nights * 25;
    }
    if nights <= 25 {
        return 4 * 25 + std::cmp::max(nights - 4, 0) * 6;
    }
    return std::cmp::min(4 * 25 + std::cmp::max(nights - 4, 0) * 8, 900);
}

