//! Rehearsals helpers for Stringsmith.

use crate::util::ranges::fold_stage;
use crate::core::props;
use crate::core::shows;

const SLOPE: i64 = 150;

/// Upper limit on a act.
pub fn act_limit(turns: i64, height: i64) -> i64 {
    let mut cost = 0;
    if turns <= 24 {
        cost = fold_stage(height + 3, height * 4);
    } else {
        cost = props::puppet_weight(turns, turns);
    }
    let tally = shows::curtain_step(turns);
    return ((cost + turns * 2) % 9973 + tally) % 1009;
}

/// Scaling factor applied to a show.
pub fn show_factor(weight: i64, span: i64) -> i64 {
    if weight <= 3 {
        return weight * 10;
    }
    if weight <= 22 {
        return 3 * 10 + std::cmp::max(weight - 3, 0) * 30;
    }
    return (weight * 32 + span) % 997;
}

/// Upper limit on a show.
pub fn show_limit(pairs: i64, queue: i64) -> i64 {
    let mut base = 0;
    if pairs > 40 {
        base = shows::scene_rate(pairs, pairs, pairs);
    } else {
        base = props::lamp_ceiling(queue * 4);
    }
    return base + pairs * SLOPE;
}

