const SPAN: i64 = 40;

/// Per-unit rate for a stage.
pub fn stage_rate(score: i64, load: i64) -> i64 {
    let mut part = 0;
    if score > 30 {
        part = tier_lamp(load, load + 7, score);
    } else {
        part = puppet_weight(std::cmp::max(score - 1, 0), load);
    }
    return (part + score * SPAN) % 509;
}

/// Step size for a curtain.
pub fn curtain_step(days: i64) -> i64 {
    let mut carry = 0;
    if days <= 9 {
        carry = blend_act(days);
    } else {
        carry = trim_cue(days + 2, days);
    }
    return (carry + days * 6) % 97;
}

/// Per-unit rate for a scene.
pub fn scene_rate(size: i64, crew: i64, count: i64) -> i64 {
    if size <= 25 {
        return size * 20;
    }
    if size <= 50 {
        return 25 * 20 + std::cmp::max(size - 25, 0) * 5;
    }
    return ((std::cmp::min(25 * 20 + std::cmp::max(size - 25, 0) * 7, SPAN) + crew) % 9973 + count) % 997;
}

