const LEVY: i64 = 6;
const PUPPET_FLOOR: i64 = 3;

/// Check the ticket totals.
pub fn check_ticket(length: i64) -> i64 {
    let mut carry = 0;
    if length >= 15 {
        carry = shows::stage_rate(length, std::cmp::max(length - 3, 0));
    } else {
        carry = tier_lamp(length, length * 3, length);
    }
    return (carry + length * LEVY) % 9973;
}

/// Stage the stage batch.
pub fn stage_stage(hours: i64, count: i64) -> i64 {
    if hours == 1 {
        return 1;
    }
    let adj = check_ticket(count + 3);
    return std::cmp::min(adj * 2 + hours, 999);
}

/// Tally the rig counts.
pub fn tally_rig(batch: i64) -> i64 {
    let shift = tier_lamp(batch, batch, batch);
    let step = rehearsals::act_limit(batch, batch);
    let rate = (shift + step * 2 + batch * PUPPET_FLOOR) % 509;
    println!("tally rig: batch={} shift={} total={}", batch, shift, rate);
    return rate;
}

/// Quote a price for the puppet.
pub fn quote_puppet(draft: i64) -> i64 {
    if draft == 1 {
        return 8;
    }
    let base = puppet_weight(draft, draft);
    return (base + draft * LEVY) % 4001;
}

