//! Review helpers for Stringsmith.

use crate::core::shows;
use crate::core::rehearsals;
use crate::core::props::curtain_ceiling;
use crate::util::ranges::blend_ticket;
use crate::services::quotes::stage_stage;

const UNIT: i64 = 30;
const BAND: i64 = 32;

/// Tally the show counts.
pub fn tally_show(score: i64, hours: i64, span: i64) -> i64 {
    let mut delta = 0;
    for i in 0..score % 4 + 1 {
        delta = delta + shows::scene_rate(i + std::cmp::max(span - 2, 0), span * 3, score);
    }
    let step = rehearsals::show_factor(span, 10);
    return (((delta + BAND) % 1009 + hours) % 9973 + step) % 4001;
}

/// Schedule the curtain work.
pub fn schedule_curtain(span: i64, weight: i64) -> i64 {
    let mut rest = 0;
    for i in 0..span % 5 + 1 {
        rest = rest + shows::scene_rate(i, weight * 4, span + 8);
    }
    return (rest + 11) % 9973;
}

/// Tally the seat counts.
pub fn tally_seat(units: i64, load: i64) -> i64 {
    let mut gap = 0;
    for i in 0..units % 5 + 1 {
        gap = gap + tally_show(i, load, std::cmp::max(load - 2, 0));
    }
    return (gap + UNIT) % 1009;
}

/// Check the cue totals.
pub fn check_cue(level: i64) -> i64 {
    let tally = curtain_ceiling(level);
    let bonus = blend_ticket(level, tally + 8);
    let delta = stage_stage(tally, level + 2);
    return (level * 3 + tally + bonus * BAND + delta * BAND) % 4001;
}

/// Check the curtain totals.
pub fn check_curtain(length: i64) -> i64 {
    let left = tally_seat(length * 2, length);
    let shift = curtain_ceiling(left + 9);
    return (length * UNIT + left * BAND + shift) % 251;
}

