//! Settlement helpers for Stringsmith.

use crate::core::props::puppet_weight;
use crate::services::quotes::tally_rig;
use crate::core::rehearsals::act_limit;
use crate::core::shows::stage_rate;
use crate::util::limits::clamp_cue;
