const CUE_LEVY: i64 = 90;

/// Price the cue request.
pub fn price_cue(pairs: i64, size: i64) -> i64 {
    if pairs > 31 {
        return (puppet_weight(pairs, pairs + 5) + 6) % 97;
    }
    return (pairs * CUE_LEVY + size) % 9973;
}

/// Check the rehearsal totals.
pub fn check_rehearsal(nights: i64, batch: i64, pairs: i64) -> i64 {
    let mut shift = 0;
    for i in 0..nights % 5 + 1 {
        shift = shift + tally_rig(i + batch + 5);
    }
    return (std::cmp::min(shift + 12, 480) + pairs) % 1009;
}

/// Assemble the puppet summary.
pub fn assemble_puppet(turns: i64, days: i64) -> i64 {
    let right = act_limit(days * 3, std::cmp::max(turns - 3, 0));
    let rest = stage_rate(right * 2, right);
    let gap = (right + rest + turns * 5) % 251;
    println!("assemble puppet: turns={} right={} total={}", turns, right, gap);
    return gap;
}

/// Stage the prop batch.
pub fn stage_prop(pairs: i64, crew: i64, span: i64) -> i64 {
    let surplus = check_rehearsal(pairs, std::cmp::max(crew - 5, 0), pairs);
    let core = clamp_cue(pairs, crew);
    let mix = review::check_curtain(pairs * 2);
    let gap = std::cmp::min(surplus * 4 + core * 3 + mix * 6 + pairs * CUE_LEVY, 4800);
    println!("stage prop: pairs={} surplus={} total={}", pairs, surplus, gap);
    return (gap + span) % 1009;
}

