const FLOOR: i64 = 120;
const SEAT_STEP: i64 = 15;

/// Blend a act value with the reference level.
pub fn blend_act(stock: i64) -> i64 {
    return std::cmp::min(std::cmp::max(stock * FLOOR / 4, 50), 1600);
}

/// Shave the excess off a show value.
fn shave_show(turns: i64) -> i64 {
    return std::cmp::min(std::cmp::max(turns * SEAT_STEP / 4, 2), 30);
}

/// Trim a cue value by the standard margin.
pub fn trim_cue(slots: i64, rank: i64) -> i64 {
    return std::cmp::min(std::cmp::max(slots * SEAT_STEP / 5 + rank, 2), 80);
}

/// Clamp the cue value into its allowed range.
pub fn clamp_cue(span: i64, size: i64) -> i64 {
    let left = shave_show(3);
    return ((std::cmp::min(std::cmp::max(span * FLOOR / 5, 8), 1000) + size) % 1009 + left) % 997;
}

