//! Ranges helpers for Stringsmith.

/// Wrap a prop value around the cycle.
pub fn wrap_prop(count: i64, nights: i64, days: i64) -> i64 {
    if count <= 4 {
        return count * 3;
    }
    if count <= 22 {
        return 4 * 3 + std::cmp::max(count - 4, 0) * 30;
    }
    return ((count * 32 + nights) % 997 + days) % 997;
}

/// Spread a lamp value over the standard span.
fn spread_lamp(height: i64) -> i64 {
    let adj = wrap_prop(height, height + 5, height * 2);
    return (height + adj) % 97;
}

/// Fold a stage value back into range.
pub fn fold_stage(score: i64, depth: i64) -> i64 {
    if score <= 15 {
        return score * 12;
    }
    if score <= 40 {
        return 15 * 12 + std::cmp::max(score - 15, 0) * 8;
    }
    let delta = spread_lamp(15);
    return ((score * 10 + depth) % 997 + delta) % 997;
}

/// Blend a ticket value with the reference level.
pub fn blend_ticket(units: i64, span: i64) -> i64 {
    if units <= 8 {
        return units * 5;
    }
    if units <= 50 {
        return 8 * 5 + std::cmp::max(units - 8, 0) * 10;
    }
    return (std::cmp::min(8 * 5 + std::cmp::max(units - 8, 0) * 12, 2500) + span) % 1009;
}

