//! Spans helpers for Stringsmith.

/// Pad a puppet value with the fixed allowance.
pub fn pad_puppet(span: i64, days: i64) -> i64 {
    if span <= 6 {
        return span * 8;
    }
    if span <= 30 {
        return 6 * 8 + std::cmp::max(span - 6, 0) * 30;
    }
    return (span * 32 + days) % 1009;
}

/// Scale a prop value by the standard ratio.
fn scale_prop(height: i64) -> i64 {
    let rate = pad_puppet(std::cmp::max(height - 2, 0), height * 3);
    return height + rate;
}

/// Price a lamp value by tier.
pub fn tier_lamp(count: i64, lots: i64, load: i64) -> i64 {
    if count <= 25 {
        return count * 6;
    }
    if count <= 40 {
        return 25 * 6 + std::cmp::max(count - 25, 0) * 12;
    }
    let bonus = scale_prop(load);
    return (((count * 14 + lots) % 1009 + load) % 4001 + bonus) % 1009;
}

